import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../../core/errors/app_failure.dart';

enum MusicKitAuthStatus { notDetermined, denied, restricted, authorized }

/// Native MusicKit features. Only iOS has an implementation; elsewhere
/// [isSupported] is false and every call throws
/// [UnsupportedPlatformFailure].
abstract interface class MusicKitBridge {
  bool get isSupported;
  Future<MusicKitAuthStatus> authorizationStatus();
  Future<MusicKitAuthStatus> requestAuthorization();

  /// Generated by MusicKit when the MusicKit App Service is enabled for the
  /// app's bundle ID; no private key ships in the app.
  Future<String> developerToken();
  Future<String> userToken(String developerToken);
  Future<({bool canPlayCatalog, bool canBecomeSubscriber})> subscription();
}

class MethodChannelMusicKitBridge implements MusicKitBridge {
  const MethodChannelMusicKitBridge();

  static const _channel = MethodChannel('moodscape/musickit');

  @override
  bool get isSupported =>
      !kIsWeb && defaultTargetPlatform == TargetPlatform.iOS;

  @override
  Future<MusicKitAuthStatus> authorizationStatus() =>
      _status('authorizationStatus');

  @override
  Future<MusicKitAuthStatus> requestAuthorization() =>
      _status('requestAuthorization');

  @override
  Future<String> developerToken() => _string('developerToken');

  @override
  Future<String> userToken(String developerToken) =>
      _string('userToken', {'developerToken': developerToken});

  @override
  Future<({bool canPlayCatalog, bool canBecomeSubscriber})>
  subscription() async {
    final raw = await _invoke<Map<Object?, Object?>>('subscription');
    return (
      canPlayCatalog: raw?['canPlayCatalogContent'] == true,
      canBecomeSubscriber: raw?['canBecomeSubscriber'] == true,
    );
  }

  Future<MusicKitAuthStatus> _status(String method) async {
    final raw = await _invoke<String>(method);
    for (final s in MusicKitAuthStatus.values) {
      if (s.name == raw) return s;
    }
    return MusicKitAuthStatus.denied;
  }

  Future<String> _string(String method, [Object? args]) async {
    final raw = await _invoke<String>(method, args);
    if (raw == null || raw.isEmpty) {
      throw const AuthFailure('Apple Music did not return a token.');
    }
    return raw;
  }

  Future<T?> _invoke<T>(String method, [Object? args]) async {
    if (!isSupported) {
      throw const UnsupportedPlatformFailure(
        'Apple Music sign-in is only available in the iOS app.',
      );
    }
    try {
      return await _channel.invokeMethod<T>(method, args);
    } on MissingPluginException {
      throw const UnsupportedPlatformFailure(
        'Apple Music is not available in this build.',
      );
    } on PlatformException catch (e) {
      // Native messages are written for users and never contain tokens.
      throw AuthFailure(e.message ?? 'Apple Music request failed.');
    }
  }
}
